class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []
        for n in nums:
            x = -1
            # Try x from 0 to n (inclusive) to find the smallest x such that x | (x+1) == n
            # Since n <= 1000, iterating up to n+1 is efficient enough.
            for candidate in range(n + 2):
                if candidate | (candidate + 1) == n:
                    x = candidate
                    break
            ans.append(x)
        return ans

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0

        for char_s, char_t in zip(s, t):
            ord_s = ord(char_s) - ord('a')
            ord_t = ord(char_t) - ord('a')

            # Calculate cost to shift forward (s[i] -> t[i])
            # If we need to go forward by k steps, the cost is k * nextCost[ord_s]
            forward_dist = (ord_t - ord_s + 26) % 26
            if forward_dist == 0:
                forward_cost = 0
            else:
                forward_cost = forward_dist * nextCost[ord_s]

            # Calculate cost to shift backward (s[i] -> t[i])
            # If we need to go backward by k steps, the cost is k * previousCost[ord_s]
            backward_dist = (ord_s - ord_t + 26) % 26
            if backward_dist == 0:
                backward_cost = 0
            else:
                backward_cost = backward_dist * previousCost[ord_s]

            # We take the minimum of going forward or backward
            total_cost += min(forward_cost, backward_cost)

        return total_cost
